mapper.insert:
INSERT INTO ctg_group_location (
    group_id, city, district, neighborhood
) VALUES (
             #{groupId}, #{city}, #{district}, #{neighborhood}
         )

INSERT INTO group_users (
    group_id, user_id, role, status, joined_at
) VALUES (
             #{groupId}, #{userId}, #{role}, #{status}, NOW()
         )

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM ctg_group
    WHERE group_name= #{groupName}
)

SELECT g.group_id, g.group_name, g.intro, g.join_message, g.created_at, g.group_status, g.owner_user_id, g.category_id, c.category_name, CONCAT(l.city, ' ', l.district, ' ', l.neighborhood) AS region,
CASE WHEN g.owner_user_id = #{loginUserId} THEN TRUE ELSE FALSE END AS owner, CASE WHEN EXISTS ( SELECT 1 FROM group_users gu WHERE gu.group_id = g.group_id AND gu.user_id = #{loginUserId} AND gu.status = 'ACTIVE' ) THEN TRUE ELSE FALSE END AS member
FROM ctg_group g LEFT JOIN ctg_categories c ON g.category_id = c.category_id LEFT JOIN ctg_group_location l ON g.group_id = l.group_id WHERE g.group_id = #{groupId}

SELECT
    CASE WHEN COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM group_users
WHERE group_id = #{groupId}
  AND user_id = #{userId}

SELECT COUNT(board_id)
FROM group_board
WHERE group_id = #{groupId}
